examples.css:
.card-demo {
  max-width: 320px;
  padding: 20px;
  border-radius: 16px;
  background: #ffffff;
  color: #1f2937;
  box-shadow: 0 10px 25px rgba(0,0,0,.15);
}
.card-demo a {
  color: #2563eb;
  font-weight: bold;
}

.primary-btn {
  border: 0;
  border-radius: 999px;
  padding: 12px 18px;
  background: #f97316;
  color: #111827;
  font-weight: 700;
}
.primary-btn:hover {
  filter: brightness(1.08);
}

.contact-form {
  display: grid;
  gap: 12px;
  max-width: 360px;
}
.contact-form input, .contact-form textarea {
  width: 100%;
  padding: 10px;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
}
.contact-form button {
  padding: 12px;
}

.cards-row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.cards-row article {
  flex: 1 1 140px;
  padding: 18px;
  border-radius: 12px;
  background: #dbeafe;
  color: #1e3a8a;
  text-align: center;
}

exercises.suggestedCss:
.product-card {
  padding: 20px;
  border-radius: 16px;
  background: #f8fafc;
  color: #111827;
  border: 1px solid #cbd5e1;
}

.cta {
  display: inline-block;
  padding: 12px 18px;
  border-radius: 999px;
  background: #22c55e;
  color: #052e16;
  text-decoration: none;
  font-weight: 700;
}

.mini-form {
  display: grid;
  gap: 10px;
  max-width: 380px;
}
.mini-form input, .mini-form textarea {
  padding: 10px;
  border-radius: 8px;
  border: 1px solid #94a3b8;
}

.layout {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.layout section {
  flex: 1 1 180px;
  padding: 16px;
  background: #e0f2fe;
  color: #0c4a6e;
}
